add_filter('cron_schedules', function($s) {
    if (!isset($s['oldies_15_minutes'])) {
        $s['oldies_15_minutes'] = ['interval' => 900, 'display' => 'Oldies 15 Minutes'];
    }
    return $s;
});
$args = [];
if (!wp_next_scheduled('oldies_news_check_sources_cron', $args)) {
    wp_schedule_event(time() + 300, 'oldies_15_minutes', 'oldies_news_check_sources_cron', $args);
}
